const iconMap={'angle-right':'chevron-right','arrow-right':'arrow-right','arrow-up':'arrow-up',award:'award',bars:'menu','bottle-water':'droplets','boxes-stacked':'boxes','bread-slice':'sandwich',building:'building-2',calendar:'calendar','calendar-check':'calendar-check',certificate:'badge-check','chart-line':'chart-no-axes-combined',check:'check','circle-check':'circle-check',clock:'clock',cow:'beef','diagram-project':'workflow',droplet:'droplet',envelope:'mail','face-smile':'smile','faucet-drip':'shower-head',feather:'feather','file-lines':'file-text',filter:'filter','flask-vial':'flask-conical',globe:'globe',headset:'headset',house:'house','layer-group':'database',leaf:'leaf','location-dot':'map-pin','magnifying-glass-chart':'search-check',microchip:'cpu','paper-plane':'send',phone:'phone',play:'play','quote-right':'quote','satellite-dish':'radio-tower',seedling:'sprout','shield-halved':'shield-check',sliders:'sliders-horizontal','solar-panel':'sun',star:'star',tractor:'tractor',tree:'trees','user-pen':'user-round-pen','user-shield':'shield-check','users-gear':'users-round',water:'waves','wheat-awn':'wheat',xmark:'x'};
function renderVectorIcons(){let count=0;document.querySelectorAll('i.fa-solid,i.fa-regular').forEach(el=>{const name=[...el.classList].find(c=>iconMap[c.slice(3)]);if(!name)return;el.setAttribute('data-lucide',iconMap[name.slice(3)]);count++});if(count)lucide.createIcons({attrs:{'stroke-width':1.8,'aria-hidden':'true',focusable:'false'}})}
renderVectorIcons();new MutationObserver(m=>{if(m.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('i.fa-solid,i.fa-regular')||n.querySelector?.('i.fa-solid,i.fa-regular')))))renderVectorIcons()}).observe(document.body,{childList:true,subtree:true});

